export default defineComponent({
  props: {
    dataStore: {
      type: "data_store",
      label: "OAuth Access Tokens Data Store"
    }
  },
  async run({ steps, $ }) {
    const traceId = steps.trigger.context.trace_id;

    // Helper function to return 401 and end workflow
    const return401 = async (reason = "") => {
      await $.respond({
        status: 401,
        body: {
          lead_id: steps.trigger.event.body.leadUuid,
          status: "error",
          reason: reason,
        }
      });
      $.flow.exit();
    };

    // 1. Validate headers exist
    const headers = steps.trigger.event.headers;

    if (!headers || !headers.authorization) {
      console.log("Could not find authorization header!");
      return await return401("invalid authorization header");
    }

    // 2. Extract Bearer token
    const authHeader = headers.authorization;
    const bearerMatch = authHeader.match(/^Bearer\s+(.+)$/i);

    if (!bearerMatch) {
      console.log("Could not find Bearer token!");
      return await return401("invalid authorization header");
    }

    const accessToken = bearerMatch[1];

    // 3. Check if token exists in data store
    let tokenData;
    try {
      tokenData = await this.dataStore.get(accessToken);
    } catch (error) {
      console.log('Error accessing data store:', error);
      return await return401("invalid authorization");
    }

    // If token doesn't exist in data store
    if (!tokenData) {
      console.log("Could not find access token in the data store!");
      return await return401("invalid authorization");
    }

    // 4. Check if token is expired
    const currentTimestamp = Math.floor(Date.now() / 1000);

    if (tokenData.expires_at && tokenData.expires_at < currentTimestamp) {
      console.log("Access token is already expired!");
      return await return401("invalid authorization");
    }
  }
});

function isBlank(name) {
  return !name || name.trim() === "" || !/[a-zA-Z]/.test(name);
};

