import { axios } from "@pipedream/platform";

async function getEquifaxToken($, username, password) {
  try {
    const tokenRequestData = 'grant_type=client_credentials&scope=https://api.equifax.com/business/oneview/consumer-credit/v1';

    const tokenResponse = await axios($, {
      method: 'post',
      url: 'https://api.equifax.com/v2/oauth/token',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      auth: {
        username,
        password
      },
      data: tokenRequestData
    });

    const responseData = tokenResponse.data || tokenResponse;

    if (responseData && responseData.access_token) {
      return responseData.access_token;
    } else {
      throw new Error("Access token not found in response");
    }
  } catch (error) {
    console.log("Token error details:", error);
    if (error.response) {
      throw new Error(`Equifax Token Error: ${error.response.status} - ${JSON.stringify(error.response.data)}`);
    } else if (error.request) {
      throw new Error(`Equifax Token Error: No response received - ${error.message}`);
    } else {
      throw new Error(`Equifax Token Error: ${error.message}`);
    }
  }
}

