async function countRecentAcroErrors($, token, spreadsheetId) {
  const response = await axios($, {
    method: "get",
    url: `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}/values/Sheet1!A:A`,
    headers: { Authorization: `Bearer ${token}` }
  });

  const rows = response.values || [];
  const fiveMinutesAgo = Date.now() - 5 * 60 * 1000;
  const recentCount = rows
    .slice(1) // skip header row if present
    .filter(([ts]) => {
      const t = new Date(ts).getTime();
      return !isNaN(t) && t >= fiveMinutesAgo;
    }).length;

  return recentCount;
}

